// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Supplier;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.EvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.TripleSource;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.StrictEvaluationStrategy;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * Review finding 3.7.5 (c), the "observer effect": a join whose runtime telemetry or cost-feedback tracking is enabled
 * never selects the count-only bound-statement guard kernels ({@code BoundStatementPattern*JoinIteration}); it runs the
 * generic {@code JoinIterator} instead. Cost-feedback tracking is enabled on every packed-plan node with a finite
 * contract prediction, so exactly the executions LEO learns from run the iterating kernel.
 * <p>
 * These tests pin the two facts the LEO-side assessment rests on: (1) the kernel switch happens (characterisation of
 * the current executor behaviour, owned by the execution-operator work package), and (2) it is result-neutral - the
 * tracked and untracked kernels return the same multiset, including duplicate statements in several contexts - while
 * only the iterating kernel produces the right-operand rows that the planner's single "dependent-iteration" join
 * implementation is priced on. The feedback of a tracked execution therefore describes the kernel the planner costed; a
 * guard kernel would not evaluate the right operand at all.
 */
class JoinGuardKernelTrackingTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:test:guard:s");
	private static final IRI P = VF.createIRI("urn:test:guard:p");
	private static final IRI P2 = VF.createIRI("urn:test:guard:p2");
	private static final Value O = VF.createLiteral("o");
	private static final Value O2 = VF.createLiteral("o2");
	private static final Resource C1 = VF.createIRI("urn:test:guard:c1");
	private static final Resource C2 = VF.createIRI("urn:test:guard:c2");
	/** (s p o) is stored twice, in two named graphs; (s p2 o2) once. */
	private static final List<Statement> STATEMENTS = List.of(
			VF.createStatement(S, P, O, C1),
			VF.createStatement(S, P, O, C2),
			VF.createStatement(S, P2, O2, C1));
	private static final int LEFT_ROWS = 3;

	@Test
	void rightBoundStatementGuardIsDeclinedUnderCostFeedbackTrackingWithoutChangingResults() {
		Supplier<Join> join = () -> new Join(boundLeft(false), sp("s", "p", "o"));

		Execution untracked = execute(join.get(), false, false, EmptyBindingSet.getInstance());
		Execution costFeedback = execute(join.get(), true, false, EmptyBindingSet.getInstance());
		Execution resultSize = execute(join.get(), false, true, EmptyBindingSet.getInstance());

		assertEquals("BoundStatementPatternJoinIteration", untracked.algorithm);
		assertEquals("JoinIterator", costFeedback.algorithm, "observer effect: tracking declines the guard kernel");
		assertEquals("JoinIterator", resultSize.algorithm, "observer effect: tracking declines the guard kernel");
		assertEquals(LEFT_ROWS * 2, untracked.rows.values().stream().mapToInt(Integer::intValue).sum(),
				"every left row joins the two stored copies of (s p o)");
		assertEquals(untracked.rows, costFeedback.rows, "the kernel switch must be result-neutral");
		assertEquals(untracked.rows, resultSize.rows, "the kernel switch must be result-neutral");
		assertEquals(0, untracked.statementLookups, "the guard kernel only counts");
		// (the statement step may serve repeated identical fully bound lookups from its direct-lookup cache)
		assertTrue(costFeedback.statementLookups > 0,
				"the tracked kernel evaluates the right operand, as dependent-iteration is priced");
		assertEquals(LEFT_ROWS * 2L, resultSize.rightResultSizeActual,
				"only the iterating kernel reports the right operand's rows to the telemetry");
	}

	@Test
	void leftBoundStatementGuardIsDeclinedUnderCostFeedbackTrackingWithoutChangingResults() {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("s", S);
		input.addBinding("p", P);
		input.addBinding("o", O);
		Supplier<Join> join = () -> new Join(sp("s", "p", "o"), xValues());

		Execution untracked = execute(join.get(), false, false, input);
		Execution costFeedback = execute(join.get(), true, false, input);

		assertEquals("BoundStatementPatternLeftJoinIteration", untracked.algorithm);
		assertEquals("JoinIterator", costFeedback.algorithm, "observer effect: tracking declines the guard kernel");
		assertEquals(2 * 2, untracked.rows.values().stream().mapToInt(Integer::intValue).sum(),
				"two stored copies of the bound left statement times two right rows");
		assertEquals(untracked.rows, costFeedback.rows, "the kernel switch must be result-neutral");
	}

	@Test
	void guardChainIsDeclinedUnderCostFeedbackTrackingWithoutChangingResults() {
		Supplier<Join> join = () -> new Join(boundLeft(true), new Join(sp("s", "p", "o"), sp("s", "p2", "o2")));

		Execution untracked = execute(join.get(), false, false, EmptyBindingSet.getInstance());
		Execution costFeedback = execute(join.get(), true, false, EmptyBindingSet.getInstance());

		assertEquals("BoundStatementPatternGuardJoinIteration", untracked.algorithm);
		assertEquals("JoinIterator", costFeedback.algorithm, "observer effect: tracking declines the guard kernel");
		assertEquals(LEFT_ROWS * 2, untracked.rows.values().stream().mapToInt(Integer::intValue).sum(),
				"each left row: two copies of (s p o) times one (s p2 o2)");
		assertEquals(untracked.rows, costFeedback.rows, "the kernel switch must be result-neutral");
	}

	private static Execution execute(Join join, boolean costFeedbackTracking, boolean trackResultSize,
			BindingSet input) {
		CountingTripleSource tripleSource = new CountingTripleSource();
		EvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
		strategy.setTrackResultSize(trackResultSize);
		join.setCostFeedbackTrackingEnabled(costFeedbackTracking);
		List<BindingSet> rows;
		try (CloseableIteration<BindingSet> result = strategy.precompile(join).evaluate(input)) {
			rows = Iterations.asList(result);
		}
		Map<String, Integer> multiset = new TreeMap<>();
		for (BindingSet row : rows) {
			multiset.merge(canonical(row), 1, Integer::sum);
		}
		return new Execution(join.getAlgorithmName(), multiset, tripleSource.statementLookups,
				join.getRightArg().getResultSizeActual());
	}

	private static String canonical(BindingSet row) {
		Map<String, String> sorted = new TreeMap<>();
		row.forEach(binding -> sorted.put(binding.getName(), binding.getValue().stringValue()));
		return sorted.toString();
	}

	private static BindingSetAssignment boundLeft(boolean withSecondPattern) {
		BindingSetAssignment left = new BindingSetAssignment();
		List<BindingSet> rows = new ArrayList<>();
		for (int i = 0; i < LEFT_ROWS; i++) {
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("s", S);
			row.addBinding("p", P);
			row.addBinding("o", O);
			if (withSecondPattern) {
				row.addBinding("p2", P2);
				row.addBinding("o2", O2);
			}
			rows.add(row);
		}
		left.setBindingSets(rows);
		left.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS, LEFT_ROWS);
		left.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_WORK_ROWS, LEFT_ROWS);
		return left;
	}

	private static BindingSetAssignment xValues() {
		BindingSetAssignment values = new BindingSetAssignment();
		List<BindingSet> rows = new ArrayList<>();
		for (int i = 0; i < 2; i++) {
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("x", VF.createLiteral(i));
			rows.add(row);
		}
		values.setBindingSets(rows);
		return values;
	}

	private static StatementPattern sp(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate), Var.of(object));
	}

	private record Execution(String algorithm, Map<String, Integer> rows, int statementLookups,
			long rightResultSizeActual) {
	}

	private static final class CountingTripleSource implements TripleSource {

		private int statementLookups;

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) {
			statementLookups++;
			return new CloseableIteratorIteration<>(matching(subj, pred, obj, contexts).iterator());
		}

		@Override
		public long getStatementCount(Resource subj, IRI pred, Value obj, Resource... contexts) {
			return matching(subj, pred, obj, contexts).size();
		}

		private static List<Statement> matching(Resource subj, IRI pred, Value obj, Resource... contexts) {
			List<Statement> matches = new ArrayList<>();
			for (Statement statement : STATEMENTS) {
				if ((subj == null || subj.equals(statement.getSubject()))
						&& (pred == null || pred.equals(statement.getPredicate()))
						&& (obj == null || obj.equals(statement.getObject()))
						&& (contexts == null || contexts.length == 0
								|| List.of(contexts).contains(statement.getContext()))) {
					matches.add(statement);
				}
			}
			return matches;
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
}
